import java.math.*;public final class InvoiceCalculator{public long totalCents(Invoice invoice){if(invoice==null||invoice.lines()==null)throw new IllegalArgumentException("invalid invoice");BigDecimal total=BigDecimal.ZERO;for(Line line:invoice.lines()){if(line==null||line.unitPrice()==null||line.quantity()<0)throw new IllegalArgumentException("invalid line");try{total=total.add(new BigDecimal(line.unitPrice()).multiply(BigDecimal.valueOf(line.quantity())));}catch(NumberFormatException e){throw new IllegalArgumentException("invalid price",e);}}return total.setScale(2,RoundingMode.HALF_EVEN).movePointRight(2).longValueExact();}}